// House Music Chord Progression Generator
const bpm = $input.first().json.bpm || 128;
const bars = $input.first().json.bars || 8;
const key = $input.first().json.key || 'A';
const scale = $input.first().json.scale || 'minor';
const voicing = $input.first().json.voicing || 'open';
const ticksPerBeat = 480;
const beatsPerBar = 4;

// Note mapping
const noteToMidi = {
  'C': 0, 'C#': 1, 'Db': 1, 'D': 2, 'D#': 3, 'Eb': 3,
  'E': 4, 'F': 5, 'F#': 6, 'Gb': 6, 'G': 7, 'G#': 8,
  'Ab': 8, 'A': 9, 'A#': 10, 'Bb': 10, 'B': 11
};

// Scale intervals
const scaleIntervals = {
  'minor': [0, 2, 3, 5, 7, 8, 10],
  'major': [0, 2, 4, 5, 7, 9, 11],
  'dorian': [0, 2, 3, 5, 7, 9, 10],
  'phrygian': [0, 1, 3, 5, 7, 8, 10]
};

// Chord types (intervals from root)
const chordTypes = {
  'minor': [0, 3, 7],           // Minor triad
  'major': [0, 4, 7],           // Major triad
  'minor7': [0, 3, 7, 10],      // Minor 7th
  'major7': [0, 4, 7, 11],      // Major 7th
  'dominant7': [0, 4, 7, 10],   // Dominant 7th
  'sus2': [0, 2, 7],            // Suspended 2nd
  'sus4': [0, 5, 7],            // Suspended 4th
  'add9': [0, 4, 7, 14]         // Add 9 (major with 9th)
};

// Get root note (octave 3 for chords - middle range)
const rootNote = noteToMidi[key] + 48; // C3 = 48
const intervals = scaleIntervals[scale] || scaleIntervals['minor'];

// Create scale notes
const scaleNotes = [];
for (let octave = 0; octave < 3; octave++) {
  intervals.forEach(interval => {
    scaleNotes.push(rootNote + interval + (octave * 12));
  });
}

// Common house music chord progressions
const progressions = {
  // Using scale degrees (0-indexed)
  'classic': [
    { degree: 0, type: 'minor7' },   // i7
    { degree: 5, type: 'major7' },   // VI7
    { degree: 3, type: 'major7' },   // IV7
    { degree: 6, type: 'dominant7' } // VII7
  ],
  'uplifting': [
    { degree: 0, type: 'minor7' },   // i7
    { degree: 4, type: 'minor7' },   // v7
    { degree: 5, type: 'major7' },   // VI7
    { degree: 3, type: 'major7' }    // IV7
  ],
  'deep': [
    { degree: 0, type: 'minor7' },   // i7
    { degree: 3, type: 'sus2' },     // IV sus2
    { degree: 6, type: 'dominant7' },// VII7
    { degree: 0, type: 'minor' }     // i
  ]
};

const progression = progressions['classic'];
const midiEvents = [];
let eventId = 0;

// Rhythm patterns for chords (house style)
const rhythmPatterns = [
  // Pattern 1: Long sustained chords
  [
    { start: 0, duration: 16, velocity: 75 }  // Whole bar
  ],
  // Pattern 2: Half note rhythm
  [
    { start: 0, duration: 8, velocity: 80 },
    { start: 8, duration: 8, velocity: 75 }
  ],
  // Pattern 3: Syncopated stabs
  [
    { start: 0, duration: 3, velocity: 85 },
    { start: 4, duration: 2, velocity: 75 },
    { start: 7, duration: 2, velocity: 70 },
    { start: 10, duration: 3, velocity: 80 },
    { start: 14, duration: 2, velocity: 75 }
  ],
  // Pattern 4: Eighth note stabs
  [
    { start: 0, duration: 1.5, velocity: 80 },
    { start: 2, duration: 1.5, velocity: 75 },
    { start: 4, duration: 1.5, velocity: 80 },
    { start: 6, duration: 1.5, velocity: 75 },
    { start: 8, duration: 1.5, velocity: 85 },
    { start: 10, duration: 1.5, velocity: 75 },
    { start: 12, duration: 1.5, velocity: 80 },
    { start: 14, duration: 1.5, velocity: 75 }
  ]
];

// Function to build chord from scale degree
function buildChord(degree, type, octaveOffset = 0) {
  const baseNote = scaleNotes[degree];
  const chordIntervals = chordTypes[type] || chordTypes['minor'];

  return chordIntervals.map(interval => {
    // For open voicing, spread notes across octaves
    if (voicing === 'open' && interval > 0) {
      return baseNote + interval + (Math.floor(interval / 7) * 5);
    }
    return baseNote + interval + (octaveOffset * 12);
  });
}

// Generate chord progression
for (let bar = 0; bar < bars; bar++) {
  const chordInfo = progression[bar % progression.length];
  const chord = buildChord(chordInfo.degree, chordInfo.type);

  // Choose rhythm pattern (vary every 2 bars)
  const patternIndex = Math.floor(bar / 2) % rhythmPatterns.length;
  const rhythmPattern = rhythmPatterns[patternIndex];

  rhythmPattern.forEach(rhythm => {
    const tick = (bar * beatsPerBar * ticksPerBeat) + (rhythm.start * ticksPerBeat / 4);
    const duration = rhythm.duration * ticksPerBeat / 4;

    // Add each note in the chord
    chord.forEach((note, idx) => {
      midiEvents.push({
        id: eventId++,
        type: 'noteOn',
        tick: tick,
        note: note,
        velocity: rhythm.velocity - (idx * 3), // Slightly decrease velocity for higher notes
        channel: 1,
        duration: duration
      });
    });
  });
}

// Sort by tick
midiEvents.sort((a, b) => a.tick - b.tick);

return {
  json: {
    instrument: 'chords',
    bpm: bpm,
    bars: bars,
    key: key,
    scale: scale,
    voicing: voicing,
    events: midiEvents,
    totalTicks: bars * beatsPerBar * ticksPerBeat,
    ticksPerBeat: ticksPerBeat,
    progression: progression.map(c => `${c.degree} ${c.type}`)
  }
};

// Convert to MIDI file format
const data = $input.first().json;
const { events, bpm, ticksPerBeat, bars, key, scale, voicing, progression } = data;

const midiData = {
  format: 0,
  tracks: 1,
  ticksPerBeat: ticksPerBeat,
  bpm: bpm,
  track: {
    name: `House Chords - ${key} ${scale}`,
    channel: 1,
    events: events.map(e => ({
      type: e.type,
      tick: e.tick,
      note: e.note,
      velocity: e.velocity,
      duration: e.duration
    }))
  },
  metadata: {
    progression: progression.join(' -> ')
  }
};

return {
  json: {
    ...data,
    midiData: midiData,
    filename: `house_chords_${key}_${scale}_${bpm}bpm_${bars}bars.mid`
  }
};
